    def tool(self, name: str) -> str:
        """One external program, through its environment variable if set."""
        key = TOOL_ENV_VARS.get(name, "")
        override = self.env.get(key) if key else None
        if override:
            return override
        if name == "md_worker":
            return ""
        if name == "fetch":
            return "curl"
        if name == "sleep":
