def load_rows(state: RunState, arm: str) -> list:
    rows = list(state.rows.get(arm) or [])
    if rows:
        return rows
    path = state.input_path(f"rows_{arm}_tag-{TAG}.jsonl")
    if path is not None:
        for line in Path(path).read_text().splitlines():
            line = line.strip()
            if line:
                try:
